command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "d395db0f40b2a3863be4216ba1644f46f42c8dc0") { throw "main moved" }
$remoteHeads = git ls-remote --heads origin work/large-folder-logical-offset work/large-folder-selection-identity
if ($LASTEXITCODE -ne 0) { throw "list remote work branches failed" }
$toDelete = @()
if ($remoteHeads -match "refs/heads/work/large-folder-logical-offset") { $toDelete += "work/large-folder-logical-offset" }
if ($remoteHeads -match "refs/heads/work/large-folder-selection-identity") { $toDelete += "work/large-folder-selection-identity" }
if ($toDelete.Count -gt 0) {
  git push origin --delete @toDelete
  if ($LASTEXITCODE -ne 0) { throw "work branch cleanup failed" }
}
git checkout main
if ($LASTEXITCODE -ne 0) { throw "checkout main failed" }
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "main fast-forward failed" }
Write-Host "LARGE_FOLDER_VIRTUALIZATION_PREP_CLEANUP_PASS"
